(function () {
    const themeBtn = document.getElementById('themeToggleBtn');
    const sidebarBtn = document.getElementById('sidebarToggleBtn');
    const savedTheme = localStorage.getItem('hw-theme');
    const savedSidebar = localStorage.getItem('hw-sidebar-hidden');
    if (savedTheme === 'dark') {
        document.documentElement.setAttribute('data-theme', 'dark');
        themeBtn.textContent = '☀️';
    }
    if (savedSidebar === '1') {
        document.body.classList.add('sidebar-hidden');
    }
    themeBtn.addEventListener('click', () => {
        const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
        if (isDark) {
            document.documentElement.removeAttribute('data-theme');
            localStorage.setItem('hw-theme', 'light');
            themeBtn.textContent = '🌙';
        } else {
            document.documentElement.setAttribute('data-theme', 'dark');
            localStorage.setItem('hw-theme', 'dark');
            themeBtn.textContent = '☀️';
        }
    });
    sidebarBtn.addEventListener('click', () => {
        document.body.classList.toggle('sidebar-hidden');
        localStorage.setItem('hw-sidebar-hidden', document.body.classList.contains('sidebar-hidden') ? '1' : '0');
    });
})();

