function cardHTML(item) {
    return `<div class="card" data-id="${item.id}">
    <div class="card-head">
      <h3>${item.title}</h3>
      <span class="badge ${item.badge[1]}">${item.badge[0]}</span>
    </div>
    <div class="body">${item.body}</div>
    <div class="foot">${item.tags.slice(0, 5).map(t => `<span class="tag">${t}</span>`).join('')}</div>
  </div>`;
}

function matches(item, q) {
    if (!q) return true;
    const hay = (item.title + ' ' + item.tags.join(' ') + ' ' + item.body).toLowerCase();
    return hay.includes(q);
}

function renderCards() {
    flowArea.style.display = 'none';
    document.getElementById('lookupArea').style.display = 'none';
    document.getElementById('practicesArea').style.display = 'none';
    document.getElementById('phrasesArea').style.display = 'none';
    document.getElementById('notesArea').style.display = 'none';
    document.getElementById('researchArea').style.display = 'none';
    cardArea.style.display = 'grid';
    const q = currentQuery.trim().toLowerCase();
    let list = KB.filter(i => (currentCat === 'all' || i.cat === currentCat) && matches(i, q));
    const [h1, p] = CAT_LABELS[currentCat] || CAT_LABELS.all;
    pagehead.querySelector('h1').textContent = h1;
    pagehead.querySelector('p').textContent = p;
    if (list.length === 0) {
        cardArea.innerHTML = '';
        emptyState.style.display = 'block';
    } else {
        emptyState.style.display = 'none';
        cardArea.innerHTML = list.map(cardHTML).join('');
    }
    resultCount.textContent = q ? `${list.length} resultado(s)` : '';
}

function renderFlowPicker() {
    cardArea.style.display = 'none';
    emptyState.style.display = 'none';
    document.getElementById('lookupArea').style.display = 'none';
    document.getElementById('practicesArea').style.display = 'none';
    document.getElementById('phrasesArea').style.display = 'none';
    document.getElementById('notesArea').style.display = 'none';
    document.getElementById('researchArea').style.display = 'none';
    flowArea.style.display = 'block';
    pagehead.querySelector('h1').textContent = 'Diagnóstico guiado';
    pagehead.querySelector('p').textContent = 'Escolha o problema relatado pelo cliente e siga os passos em ordem.';
    resultCount.textContent = '';

    let html = `<div class="flow-select" id="flowChips">`;
    FLOWS.forEach((f, idx) => {
        html += `<button class="flow-chip" data-flow="${f.id}">${f.label}</button>`;
    });
    html += `</div><div id="flowSteps"></div>`;
    flowArea.innerHTML = html;

    flowArea.querySelectorAll('.flow-chip').forEach(chip => {
        chip.addEventListener('click', () => {
            flowArea.querySelectorAll('.flow-chip').forEach(c => c.classList.remove('active'));
            chip.classList.add('active');
            renderFlowSteps(chip.dataset.flow);
        });
    });
    // auto-select first
    const first = flowArea.querySelector('.flow-chip');
    if (first) { first.classList.add('active'); renderFlowSteps(first.dataset.flow); }
}

function renderFlowSteps(flowId) {
    const flow = FLOWS.find(f => f.id === flowId);
    const box = document.getElementById('flowSteps');
    if (!flow || !box) return;
    let html = `<div class="steps">`;
    flow.steps.forEach((s, i) => {
        html += `<div class="step" data-n="${i + 1}">
      <div class="stepcard">
        <h4>${s.t}</h4>
        <div class="body">${s.b}</div>
      </div>
    </div>`;
    });
    html += `</div>`;
    box.innerHTML = html;
}

