function matchByList(ip, list) {
    if (!ip) return null;
    for (const s of list) {
        if (s.exact && s.exact.includes(ip)) return s;
        if (s.prefixes && s.prefixes.some(p => ip.startsWith(p))) return s;
    }
    return null;
}
function matchEmailServer(ip) { return matchByList(ip, EMAIL_SERVERS); }
function matchSiteOrPlesk(ip) {
    const site = matchByList(ip, SITE_SERVERS);
    if (site) return { ...site, kind: 'cpanel' };
    const plesk = matchByList(ip, PLESK_SERVERS);
    if (plesk) return { ...plesk, kind: 'plesk' };
    return null;
}

// DoH — tenta dns.google, cai para cloudflare-dns.com se falhar
async function dnsQuery(name, type) {
    const providers = [
        `https://dns.google/resolve?name=${encodeURIComponent(name)}&type=${type}`,
        `https://cloudflare-dns.com/dns-query?name=${encodeURIComponent(name)}&type=${type}`
    ];
    let lastErr;
    for (const url of providers) {
        try {
            const res = await fetchT(url, { headers: { accept: 'application/dns-json' } }, 6000);
            if (!res.ok) throw new Error('HTTP ' + res.status);
            return await res.json();
        } catch (e) { lastErr = e; }
    }
    throw lastErr || new Error('DNS lookup falhou');
}

async function getRecords(name, type) {
    try {
        const data = await dnsQuery(name, type);
        if (data.Status !== 0 || !data.Answer) return [];
        return data.Answer.filter(a => String(a.type) === String(TYPE_NUM[type]) || true).map(a => a.data);
    } catch (e) { return null; } // null = erro de consulta (diferente de "vazio")
}
const TYPE_NUM = { A: 1, NS: 2, CNAME: 5, MX: 15, TXT: 16 };

// Consulta os DOIS resolvers públicos em paralelo (não só como fallback de erro)
// e devolve se eles concordam + o TTL — isso expõe cache desatualizado/propagação em andamento,
// que é a causa mais comum de "a ferramenta disse um servidor errado".
async function dnsQueryDual(name, type) {
    const providers = [
        { key: 'google', url: `https://dns.google/resolve?name=${encodeURIComponent(name)}&type=${type}` },
        { key: 'cloudflare', url: `https://cloudflare-dns.com/dns-query?name=${encodeURIComponent(name)}&type=${type}` }
    ];
    return Promise.all(providers.map(async p => {
        try {
            const res = await fetchT(p.url, { headers: { accept: 'application/dns-json' } }, 6000);
            if (!res.ok) throw new Error('HTTP ' + res.status);
            const data = await res.json();
            const ok = data.Status === 0 && Array.isArray(data.Answer) && data.Answer.length > 0;
            return {
                key: p.key, ok,
                values: ok ? data.Answer.map(a => a.data) : [],
                ttl: ok ? data.Answer[0].TTL : null,
            };
        } catch (e) { return { key: p.key, ok: false, values: [], ttl: null }; }
    }));
}

// Igual a getRecords, mas cross-checado entre os dois resolvers.
// Retorna {values, ttl, agree} onde agree: true=os dois bateram | false=divergiram | null=só 1 respondeu.
async function getRecordsChecked(name, type) {
    const sources = await dnsQueryDual(name, type);
    const ok = sources.filter(s => s.ok);
    if (!ok.length) return { values: [], ttl: null, agree: null, sources };
    const primary = ok[0];
    const agree = ok.length > 1 ? ok.every(s => JSON.stringify(s.values) === JSON.stringify(primary.values)) : null;
    return { values: primary.values, ttl: primary.ttl, agree, sources };
}

function fmtTTL(sec) {
    if (sec == null) return '—';
    if (sec < 90) return `${sec}s`;
    const min = Math.round(sec / 60);
    if (min < 90) return `${sec}s (~${min} min)`;
    return `${sec}s (~${(sec / 3600).toFixed(1)}h)`;
}

// Listas de bloqueio (DNSBL). SORBS foi desativado em jun/2024 e saiu da lista.
// weak:true = listas que costumam recusar/ignorar consultas vindas de resolvers públicos.
const RBLS = [
    { zone: 'zen.spamhaus.org', label: 'Spamhaus ZEN', weak: true },
    { zone: 'bl.spamcop.net', label: 'SpamCop' },
    { zone: 'b.barracudacentral.org', label: 'Barracuda', weak: true },
    { zone: 'psbl.surriel.com', label: 'PSBL' },
    { zone: 'dnsbl-1.uceprotect.net', label: 'UCEPROTECT L1' },
    { zone: 'dnsbl.dronebl.org', label: 'DroneBL' },
    { zone: 'spam.spamrats.com', label: 'SpamRATS' },
];

async function checkRbl(ip, zone) {
    const rev = ip.split('.').reverse().join('.');
    try {
        const data = await dnsQuery(`${rev}.${zone}`, 'A');
        if (data.Status === 0 && data.Answer && data.Answer.length) {
            const codes = data.Answer.filter(a => a.type === 1).map(a => a.data);
            // 127.255.255.x = a lista recusou a consulta (resolver público/limite) — NÃO é listagem
            if (codes.length && codes.every(c => /^127\.255\.255\./.test(c))) {
                return { listed: null, detail: 'consulta recusada pela lista (resolver público)' };
            }
            return { listed: true, detail: codes.join(', ') };
        }
        return { listed: false };
    } catch (e) {
        return { listed: null, detail: 'sem resposta' };
    }
}

const DKIM_GUESSES = ['default', 'selector1', 'selector2', 'google', 'k1', 'k2', 'mail', 'dkim', 's1', 's2', 'key1', 'smtp', 'email'];

// ---------- utilidades ----------
function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
function fetchT(url, opts, ms) {
    const ctl = new AbortController();
    const t = setTimeout(() => ctl.abort(), ms || 8000);
    return fetch(url, { ...(opts || {}), signal: ctl.signal }).finally(() => clearTimeout(t));
}
const unq = t => String(t).replace(/"\s+"/g, '').replace(/^"|"$/g, '');   // junta TXT em vários pedaços
const ipv4 = list => (list || []).filter(v => /^\d{1,3}(\.\d{1,3}){3}$/.test(v));
const RT_NAMES = { 1: 'A', 2: 'NS', 5: 'CNAME', 6: 'SOA', 12: 'PTR', 15: 'MX', 16: 'TXT', 28: 'AAAA', 257: 'CAA' };

async function dnsAnswers(name, type) {
    try {
        const d = await dnsQuery(name, type);
        if (d.Status !== 0 || !d.Answer) return [];
        return d.Answer.map(a => ({ type: RT_NAMES[a.type] || String(a.type), data: a.data, ttl: a.TTL }));
    } catch (e) { return null; }
}
async function getPtr(ip) {
    const r = await getRecords(ip.split('.').reverse().join('.') + '.in-addr.arpa', 'PTR');
    return Array.isArray(r) && r.length ? r[0].replace(/\.$/, '') : null;
}
function parseMx(list) {
    if (!Array.isArray(list)) return [];
    return list.map(s => { const p = s.trim().split(/\s+/); return { pri: parseInt(p[0], 10) || 0, host: (p.slice(1).join('') || '').replace(/\.$/, '') }; })
        .filter(x => x.host).sort((a, b) => a.pri - b.pri);
}
function ttlShort(s) { if (s == null) return ''; if (s < 90) return s + 's'; const m = Math.round(s / 60); return m < 90 ? m + 'min' : (s / 3600).toFixed(1).replace(/\.0$/, '') + 'h'; }

// Domínio registrável (o RDAP só conhece o domínio registrado, não subdomínios)
const BR_SLD = new Set(['com', 'net', 'org', 'edu', 'gov', 'mil', 'ind', 'adv', 'med', 'eco', 'blog', 'app', 'dev', 'art', 'arq', 'bio', 'esp', 'far', 'fnd', 'fot', 'jus', 'mus', 'pro', 'tur', 'vet', 'wiki', 'tv', 'fm', 'ong', 'eng', 'psi', 'rec', 'srv', 'tec', 'emp', 'coop', 'inf', 'etc', 'flog', 'nom', 'ntr', 'odo', 'qsl', 'slg', 'trd', 'vlog', 'zlg']);
const SLD_2 = new Set(['co.uk', 'org.uk', 'ac.uk', 'gov.uk', 'com.au', 'net.au', 'org.au', 'co.nz', 'co.za', 'com.ar', 'com.mx', 'com.pt', 'co.jp', 'com.co', 'com.pe', 'com.uy', 'com.py', 'com.bo', 'com.ve', 'com.ec', 'com.cl', 'com.cn', 'com.tr', 'co.in', 'co.il']);
function registrable(domain) {
    const p = domain.split('.'); if (p.length <= 2) return domain;
    const last2 = p.slice(-2).join('.');
    if (p[p.length - 1] === 'br') return BR_SLD.has(p[p.length - 2]) ? p.slice(-3).join('.') : last2;
    return SLD_2.has(last2) ? p.slice(-3).join('.') : last2;
}

// ---------- RDAP universal (substitui o whois manual: .br e internacionais) ----------
// RDAP é o sucessor oficial do WHOIS. Para .br usamos o servidor do registro.br;
// para o resto, o bootstrap oficial da IANA diz qual servidor RDAP atende cada extensão.
const RDAP_FALLBACK = { com: 'https://rdap.verisign.com/com/v1/', net: 'https://rdap.verisign.com/net/v1/', org: 'https://rdap.publicinterestregistry.org/rdap/' };
let _rdapBoot = null;
async function rdapBaseFor(domain) {
    const tld = domain.split('.').pop().toLowerCase();
    if (tld === 'br') return 'https://rdap.registro.br/';
    if (!_rdapBoot) {
        try {
            const r = await fetchT('https://data.iana.org/rdap/dns.json', {}, 7000);
            if (!r.ok) throw new Error('HTTP ' + r.status);
            _rdapBoot = (await r.json()).services || [];
        } catch (e) { _rdapBoot = []; }
    }
    for (const svc of _rdapBoot) {
        if (svc[0].some(t => t.toLowerCase() === tld)) {
            const u = svc[1].find(x => /^https:/i.test(x)) || svc[1][0];
            return u.endsWith('/') ? u : u + '/';
        }
    }
    return RDAP_FALLBACK[tld] || null;
}

async function queryRdap(domain) {
    const base = await rdapBaseFor(domain);
    if (!base) return { ok: false, reason: 'norsdap' };
    try {
        const res = await fetchT(`${base}domain/${encodeURIComponent(domain)}`, { headers: { accept: 'application/rdap+json' } }, 9000);
        if (res.status === 404) return { ok: false, reason: 'notfound' };
        if (res.status === 429) return { ok: false, reason: 'ratelimit' };
        if (!res.ok) return { ok: false, reason: 'http', detail: res.status };
        const data = await res.json();
        const events = Array.isArray(data.events) ? data.events : [];
        const findEvent = re => { const e = events.find(ev => re.test(ev.eventAction || '')); return e ? e.eventDate : null; };
        let registrar = null;
        (data.entities || []).forEach(en => {
            if (registrar || !(en.roles || []).includes('registrar')) return;
            const fn = ((en.vcardArray || [])[1] || []).find(x => x[0] === 'fn');
            registrar = fn ? fn[3] : (en.handle || null);
        });
        return {
            ok: true, source: new URL(base).host,
            status: Array.isArray(data.status) ? data.status : [],
            created: findEvent(/registration/i),
            expires: findEvent(/expiration/i),
            lastChanged: findEvent(/last changed/i) || findEvent(/last update(?! of rdap)/i),
            nameservers: Array.isArray(data.nameservers) ? data.nameservers.map(n => n.ldhName).filter(Boolean).map(n => n.toLowerCase()) : [],
            registrar,
            dnssec: data.secureDNS ? !!data.secureDNS.delegationSigned : null,
        };
    } catch (e) {
        return { ok: false, reason: (e && e.name === 'AbortError') ? 'timeout' : 'network' };
    }
}

function fmtRdapDate(iso) {
    if (!iso) return null;
    const d = new Date(iso);
    if (isNaN(d.getTime())) return iso;
    return d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' });
}
const RDAP_LABELS = {
    'inactive': 'congelado', 'active': 'ativo', 'ok': 'ativo',
    'client transfer prohibited': 'transferência bloqueada', 'server transfer prohibited': 'transferência bloqueada (registry)',
    'client delete prohibited': 'exclusão bloqueada', 'server delete prohibited': 'exclusão bloqueada (registry)',
    'client update prohibited': 'alteração bloqueada', 'server update prohibited': 'alteração bloqueada (registry)',
    'client hold': 'suspenso (hold)', 'server hold': 'suspenso (hold)',
    'pending delete': 'exclusão pendente', 'redemption period': 'período de resgate', 'pending transfer': 'transferência pendente'
};
const rdapBad = s => { s = String(s).toLowerCase(); return s === 'inactive' || /hold|delete(?! prohibited)|suspend|redemption|expired/.test(s); };
function rdapStatusLabel(status) { return RDAP_LABELS[String(status).toLowerCase()] || status; }
function rdapStatusPill(status) {
    const s = String(status).toLowerCase();
    if (rdapBad(s)) return pill(esc(rdapStatusLabel(status)), 'fail');
    if (s === 'active' || s === 'ok') return pill(esc(rdapStatusLabel(status)), 'ok');
    return pill(esc(rdapStatusLabel(status)), 'mut');
}
function rdapExpiryPill(expiresIso) {
    if (!expiresIso) return '';
    const exp = new Date(expiresIso);
    if (isNaN(exp.getTime())) return '';
    const diffDays = Math.floor((exp - new Date()) / 86400000);
    if (diffDays < 0) return pill('EXPIRADO', 'fail');
    if (diffDays <= 30) return pill(`expira em ${diffDays}d`, 'warn');
    return pill('em dia', 'ok');
}
function rdapVerdict(r) {
    if (!r || !r.ok) return 'na';
    if (r.status.some(rdapBad)) return 'fail';
    if (r.expires) {
        const d = Math.floor((new Date(r.expires) - new Date()) / 86400000);
        if (d < 0) return 'fail';
        if (d <= 30) return 'warn';
    }
    return 'ok';
}
// Linha do tempo: do registro até a expiração, com marcador de "hoje"
function expiryGauge(created, expires) {
    const exp = new Date(expires), now = new Date(), cr = created ? new Date(created) : null;
    if (isNaN(exp.getTime())) return '';
    const days = Math.floor((exp - now) / 86400000);
    let pct = 100;
    if (cr && !isNaN(cr.getTime()) && exp > cr) pct = Math.max(2, Math.min(100, ((now - cr) / (exp - cr)) * 100));
    const tone = days < 0 ? 'fail' : (days <= 30 ? 'warn' : 'ok');
    const lbl = days < 0 ? `expirou há ${-days} dia(s)` : (days === 0 ? 'expira hoje' : `faltam ${days} dia(s)`);
    return `<div class="gauge">
    <div class="gauge-bar"><div class="gauge-fill ${tone}" style="--w:${pct.toFixed(1)}%"></div><div class="gauge-mark" style="--w:${pct.toFixed(1)}%"></div></div>
    <div class="gauge-lbl"><span>${esc(fmtRdapDate(created) || 'início desconhecido')}</span><span class="gauge-days">${lbl}</span><span>${esc(fmtRdapDate(expires))}</span></div>
  </div>`;
}
function rdapCardBody(ctx, r) {
    const manual = `<div class="lk-manual" style="margin-top:12px;"><a href="https://www.whois.com/whois/${esc(ctx.reg)}" target="_blank" rel="noopener">whois.com ↗</a><a href="https://registro.br/tecnologia/ferramentas/whois/" target="_blank" rel="noopener">registro.br ↗</a></div>`;
    if (!r.ok) {
        const msgs = {
            notfound: 'Domínio não encontrado no RDAP — pode estar disponível para registro ou grafado errado.',
            ratelimit: 'O RDAP recusou a consulta por excesso de requisições. Tente novamente em alguns instantes.',
            network: 'Não foi possível consultar o RDAP direto pelo navegador (rede instável ou bloqueio de CORS). Use um link manual:',
            timeout: 'O servidor RDAP demorou demais para responder. Tente novamente ou use um link manual:',
            norsdap: 'Esta extensão não publica RDAP acessível pelo navegador. Use um link manual:',
            http: `O RDAP retornou um erro inesperado (HTTP ${esc(r.detail || '?')}).`,
        };
        return `<div class="callout warn" style="margin:0;">${msgs[r.reason] || msgs.network}</div>${r.reason === 'notfound' ? '' : manual}`;
    }
    const status = r.status.length ? r.status.map(rdapStatusPill).join(' ') : pill('sem status informado', 'mut');
    const dnssec = r.dnssec === null ? '—' : (r.dnssec ? 'assinado' : 'não assinado');
    return `<div class="kpis">
      <div class="kpi"><span class="l">Status</span><div style="display:flex;flex-wrap:wrap;gap:4px;">${status}</div></div>
      <div class="kpi"><span class="l">Expira em</span><b>${esc(fmtRdapDate(r.expires) || '—')}</b>${rdapExpiryPill(r.expires)}</div>
      <div class="kpi"><span class="l">Criado em</span><b>${esc(fmtRdapDate(r.created) || '—')}</b></div>
      <div class="kpi"><span class="l">Última alteração</span><b>${esc(fmtRdapDate(r.lastChanged) || '—')}</b></div>
      <div class="kpi"><span class="l">Registrar</span><b>${esc(r.registrar || '—')}</b></div>
      <div class="kpi"><span class="l">DNSSEC</span><b>${dnssec}</b></div>
    </div>
    ${r.expires ? expiryGauge(r.created, r.expires) : ''}
    <p class="lkc-foot">Fonte: RDAP oficial (<code>${esc(r.source)}</code>) · domínio consultado: <code>${esc(ctx.reg)}</code>${ctx.reg !== ctx.domain ? ' (domínio registrável de ' + esc(ctx.domain) + ')' : ''}</p>`;
}

function normalizeDomain(raw) {
    let d = raw.trim().toLowerCase();
    d = d.replace(/^https?:\/\//, '').replace(/\/.*$/, '');
    if (d.startsWith('mail.')) d = d.slice(5);
    if (d.startsWith('www.')) d = d.slice(4);
    return d;
}

// Preserva o "mail." (se o usuário digitou) — usado nos links de busca externa
function cleanQueryTerm(raw) {
    let d = raw.trim().toLowerCase();
    d = d.replace(/^https?:\/\//, '').replace(/\/.*$/, '');
    if (d.startsWith('www.')) d = d.slice(4);
    return d;
}

function pill(text, kind) { return `<span class="pill ${kind}">${text}</span>`; }
function row(k, v, note) { return `<div class="lk-row"><div class="k">${k}</div><div class="v${note ? ' note' : ''}">${v}</div></div>`; }

