function addCheck(ctx, id, label, status, weight) {
    ctx.checks = ctx.checks.filter(c => c.id !== id);
    ctx.checks.push({ id, label, status, weight });
    renderScore(ctx);
}
function renderScore(ctx) {
    if (ctx.token !== lookupToken) return;
    const val = { ok: 1, warn: .5, fail: 0 };
    const live = ctx.checks.filter(c => c.status !== 'na');
    const wsum = live.reduce((a, c) => a + c.weight, 0);
    const score = wsum ? Math.round(live.reduce((a, c) => a + val[c.status] * c.weight, 0) / wsum * 100) : null;
    const arc = document.getElementById('lkArc'), num = document.getElementById('lkScore'), chips = document.getElementById('lkChips');
    if (!arc) return;
    const C = 2 * Math.PI * 40;
    if (score !== null) {
        arc.setAttribute('stroke-dasharray', `${(C * score / 100).toFixed(1)} ${C.toFixed(1)}`);
        arc.setAttribute('stroke', score >= 85 ? '#4ADE80' : (score >= 60 ? '#F5A524' : '#F0605B'));
        num.textContent = score;
    }
    const icon = { ok: '✓', warn: '!', fail: '✕', na: '–' };
    chips.innerHTML = ctx.checks.map(c => `<span class="lkd-chip ${c.status === 'na' ? 'pend' : c.status}">${icon[c.status]} ${esc(c.label)}</span>`).join('');
    ctx.score = score;
}

function serverTile(label, ico, ip, ipRes, isMail, prov) {
    if (!ip) return `<div class="srv"><div class="srv-h">${ico} ${label}</div><div class="srv-name">sem IP</div><div class="srv-note">Nenhum registro A encontrado para ${isMail ? 'mail.&lt;domínio&gt; nem para o MX' : 'o domínio'}.</div></div>`;
    const ttl = `TTL ${fmtTTL(ipRes.ttl)}`;
    const agree = ipRes.agree === false ? pill('resolvers divergem', 'fail') : (ipRes.agree === null ? pill('1 resolver só', 'mut') : pill('2 resolvers concordam', 'ok'));
    let name = 'Servidor externo', tone = 'warn', kind = 'não consta na lista interna', link = '', extra = '', note = '';
    if (ipRes.agree === false) {
        const alt = (ipRes.sources || []).map(s => s.values[0]).find(v => v && v !== ip) || '?';
        name = 'Indefinido'; tone = 'fail'; kind = 'propagação em andamento?';
        note = `Google e Cloudflare devolveram IPs diferentes (${esc(ip)} × ${esc(alt)}) — provável <strong>propagação de DNS em andamento</strong>. Refaça em alguns minutos.`;
    } else {
        const s = isMail ? matchEmailServer(ip) : matchSiteOrPlesk(ip);
        if (s) {
            name = s.name; tone = 'ok';
            kind = s.kind === 'plesk' ? 'Plesk' : (isMail ? 'cPanel (e-mail)' : 'cPanel (site)');
            link = `<a class="srv-go" href="${esc(s.url)}" target="_blank" rel="noopener">Abrir painel ↗</a>`;
            if (s.kind === 'plesk' && s.acesso === false) { extra = pill('SEM ACESSO — este Plesk não é gerenciado por nós', 'fail'); tone = 'fail'; }
            note = 'Heurística por faixa de IP — confirme no painel se a decisão for crítica.';
        } else if (isMail && prov && prov !== 'Hostweb/Secrelnet') {
            name = prov; tone = 'ok'; kind = 'provedor externo';
            note = 'O MX aponta para um provedor de e-mail externo — não há painel nosso para este e-mail.';
        } else if (isMail) {
            name = 'Provável Postfix/Zimbra'; tone = 'warn'; kind = 'confirmar por telnet';
            note = 'IP fora das faixas cPanel conhecidas. Veja o card de assinatura abaixo.';
        } else {
            note = 'IP fora das faixas cPanel/Plesk conhecidas — site hospedado fora da nossa infraestrutura.';
        }
    }
    return `<div class="srv ${tone}"><div class="srv-h">${ico} ${label}</div>
    <div class="srv-name">${esc(name)}</div><div class="srv-ip">${esc(ip)} · ${ttl}</div>
    <div class="srv-pills">${pill(esc(kind), tone === 'ok' ? 'ok' : (tone === 'fail' ? 'fail' : 'warn'))} ${agree} ${extra}</div>
    <div class="srv-note">${note}</div>${link ? `<div style="margin-top:10px;">${link}</div>` : ''}</div>`;
}

function mailProvider(mxList) {
    const h = mxList.map(x => x.host.toLowerCase()).join(' ');
    if (/google\.com|googlemail\.com/.test(h)) return 'Google Workspace';
    if (/protection\.outlook\.com|outlook\.com/.test(h)) return 'Microsoft 365';
    if (/zoho\./.test(h)) return 'Zoho Mail';
    if (/mimecast|pphosted|proofpoint|barracuda|mailgun|sendgrid/.test(h)) return 'Gateway/filtro de e-mail';
    if (/secrel\.com\.br|hostweb\.com\.br/.test(h)) return 'Hostweb/Secrelnet';
    return null;
}
async function spfLookups(spf, depth, seen, box) {
    depth = depth || 0; seen = seen || new Set(); box = box || { n: 0 };
    for (const t of spf.split(/\s+/).slice(1)) {
        const m = t.replace(/^[+\-~?]/, '');
        if (/^(a|mx|ptr)(:|\/|$)/i.test(m) || /^exists:/i.test(m)) { box.n++; }
        else if (/^(include:|redirect=)/i.test(m)) {
            box.n++;
            const d = m.replace(/^(include:|redirect=)/i, '');
            if (depth < 4 && seen.size < 12 && !seen.has(d)) {
                seen.add(d);
                const r = await getRecords(d, 'TXT');
                const s = Array.isArray(r) ? r.map(unq).find(x => /^v=spf1/i.test(x)) : null;
                if (s) await spfLookups(s, depth + 1, seen, box);
            }
        }
    }
    return box.n;
}
function authTile(title, pillHtml, detail, rec) {
    return `<div class="auth"><div class="auth-h"><b>${title}</b>${pillHtml}</div><div class="auth-d">${detail}</div>${rec ? `<details><summary>ver registro</summary><code>${esc(rec)}</code></details>` : ''}</div>`;
}
const recRow = (t, v, ttl) => `<div class="dm-row"><span class="rt rt-${t}">${t}</span><span class="dm-v">${v}</span><span class="dm-ttl">${ttl != null ? ttlShort(ttl) : ''}</span></div>`;
const SUBS = ['www', 'mail', 'webmail', 'smtp', 'pop', 'imap', 'ftp', 'cpanel', 'autodiscover', 'autoconfig', 'ns1', 'ns2', 'webdisk', 'whm'];

// ---------- execução ----------
async function runLookup() {
    const raw = document.getElementById('lkInput').value;
    if (!raw || !raw.trim()) return;
    const domain = normalizeDomain(raw);
    const queryTerm = cleanQueryTerm(raw);
    const isBr = /\.br$/i.test(domain);
    const results = document.getElementById('lkResults');
    const goBtn = document.getElementById('lkGo');
    const copyBtn = document.getElementById('lkCopy');
    goBtn.disabled = true; goBtn.textContent = 'Consultando…';
    copyBtn.style.display = 'none';

    const token = ++lookupToken;
    const t0 = Date.now();
    const ctx = { token, domain, queryTerm, isBr, reg: registrable(domain), checks: [], rep: {}, total: 6, done: 0 };
    results.innerHTML = dashShell(ctx);
    renderScore(ctx);

    function finish() {
        ctx.done++;
        if (ctx.token !== lookupToken) return;
        const bar = document.getElementById('lkProg'); if (bar) bar.style.width = Math.round(ctx.done / ctx.total * 100) + '%';
        if (ctx.done < ctx.total) return;
        const box = document.getElementById('lkProgBox'); if (box) box.style.opacity = '0';
        const sub = document.getElementById('lkSub'); if (sub) sub.textContent = `Concluído em ${((Date.now() - t0) / 1000).toFixed(1)}s · indicador de saúde é heurístico`;
        const r = ctx.rep;
        lastLookupText = [
            `Consulta: ${domain}` + (ctx.score != null ? `  |  Saúde (heurística): ${ctx.score}/100` : ''),
            r.rdap, r.site, r.mailsrv, r.mx, r.ns, r.spf, r.dmarc, r.dkim, r.rbl, r.fp
        ].filter(Boolean).join('\n');
        copyBtn.style.display = 'inline-block';
        goBtn.disabled = false; goBtn.textContent = 'Analisar';
    }
    const guard = (id, fn) => Promise.resolve().then(fn).catch(err => {
        setCard(ctx, id, `<div class="callout warn" style="margin:0;">Não foi possível concluir esta verificação (${esc(err && err.message || 'erro inesperado')}). Tente novamente.</div>`, pill('erro', 'mut'));
    }).finally(finish);

    // ---- buscas base, todas em paralelo ----
    const pRdap = queryRdap(ctx.reg);
    const pSite = getRecordsChecked(domain, 'A');
    const pMailA = getRecordsChecked('mail.' + domain, 'A');
    const pMx = getRecords(domain, 'MX');
    const pNs = getRecords(domain, 'NS');
    const pTxt = getRecords(domain, 'TXT');
    const pExtra = Promise.all([dnsAnswers(domain, 'AAAA'), dnsAnswers(domain, 'SOA'), dnsAnswers(domain, 'CAA')]);
    const pSubs = Promise.all(SUBS.map(async s => ({ s, ans: await dnsAnswers(`${s}.${domain}`, 'A') })));
    const pMail = (async () => {
        const [mailRes, mx] = await Promise.all([pMailA, pMx]);
        const mxList = parseMx(mx);
        const mxHost = mxList.length ? mxList[0].host : null;
        const direct = ipv4(mailRes.values)[0] || null;
        let ipRes = mailRes;
        if (!direct && mxHost) ipRes = await getRecordsChecked(mxHost, 'A');
        return { mxList, mxHost, ip: direct || ipv4(ipRes.values)[0] || null, ipRes };
    })();

    await Promise.allSettled([

        // 1) Registro (RDAP .br e internacional)
        guard('rdap', async () => {
            const r = await pRdap;
            ctx.rdap = r;
            const st = r.ok ? (r.expires ? rdapExpiryPill(r.expires) : '') : pill('indisponível', 'mut');
            setCard(ctx, 'rdap', rdapCardBody(ctx, r), st);
            addCheck(ctx, 'rdap', 'Registro', rdapVerdict(r), 3);
            ctx.rep.rdap = r.ok
                ? `Registro (${r.source}): status=${r.status.map(rdapStatusLabel).join(', ') || '—'} | criado=${fmtRdapDate(r.created) || '—'} | expira=${fmtRdapDate(r.expires) || '—'} | últ. alteração=${fmtRdapDate(r.lastChanged) || '—'} | registrar=${r.registrar || '—'}`
                : `Registro: não obtido (${r.reason})`;
        }),

        // 2) Servidores (site + e-mail)
        guard('srv', async () => {
            const [site, mail] = await Promise.all([pSite, pMail]);
            const siteIP = ipv4(site.values)[0] || null;
            ctx.siteIP = siteIP; ctx.mailIP = mail.ip;
            setCard(ctx, 'srv',
                `<div class="srv-grid">${serverTile('Site', '🌐', siteIP, site, false)}${serverTile('E-mail', '✉️', mail.ip, mail.ipRes, true, mailProvider(mail.mxList))}</div>
         <p class="lkc-foot">O IP vem de resolvers públicos (Google/Cloudflare), não do servidor autoritativo — se o apontamento mudou há pouco, pode estar em cache. Por isso cada IP mostra o TTL e se os dois resolvers concordaram.</p>`,
                pill(siteIP || mail.ip ? 'identificado' : 'sem IP', siteIP || mail.ip ? 'ok' : 'warn'));
            addCheck(ctx, 'site', 'Site resolve', siteIP ? 'ok' : 'fail', 2);
            addCheck(ctx, 'res', 'Resolvers', [site, mail.ipRes].some(x => x.agree === false) ? 'warn' : 'ok', 1);
            const sn = siteIP ? (matchSiteOrPlesk(siteIP)?.name || 'não reconhecido') : '—';
            const extProv = mailProvider(mail.mxList);
            const mn = mail.ip ? (matchEmailServer(mail.ip)?.name || ((extProv && extProv !== 'Hostweb/Secrelnet') ? extProv : 'confirmar por telnet')) : '—';
            const ag = x => x.agree === false ? 'resolvers DIVERGEM' : (x.agree === null ? '1 resolver só' : '2 resolvers concordam');
            ctx.rep.site = `IP site: ${siteIP || '—'} (TTL ${fmtTTL(site.ttl)}, ${ag(site)}) | Servidor: ${sn}`;
            ctx.rep.mailsrv = `IP e-mail: ${mail.ip || '—'} (TTL ${fmtTTL(mail.ipRes.ttl)}, ${ag(mail.ipRes)}) | Servidor: ${mn}`;
        }),

        // 3) E-mail: MX, PTR, SPF, DKIM, DMARC, MTA-STS
        guard('mail', async () => {
            const [m, txt] = await Promise.all([pMail, pTxt]);
            const txtList = Array.isArray(txt) ? txt.map(unq) : [];
            const spfs = txtList.filter(t => /^v=spf1/i.test(t));
            const spf = spfs[0] || null;
            const [dmarcTxt, stsTxt, dkimChecks, mxInfo, spfN] = await Promise.all([
                getRecords('_dmarc.' + domain, 'TXT'),
                getRecords('_mta-sts.' + domain, 'TXT'),
                Promise.all(DKIM_GUESSES.map(async sel => {
                    const r = await getRecords(`${sel}._domainkey.${domain}`, 'TXT');
                    const val = Array.isArray(r) ? r.map(unq).find(t => /v=dkim1|k=rsa|p=/i.test(t)) : null;
                    return val ? { sel, val } : null;
                })),
                Promise.all(m.mxList.slice(0, 4).map(async x => {
                    const ip = ipv4(await getRecords(x.host, 'A'))[0] || null;
                    const ptr = ip ? await getPtr(ip) : null;
                    const back = ptr ? ipv4(await getRecords(ptr, 'A')) : [];
                    return { ...x, ip, ptr, fcrdns: !!(ip && back.includes(ip)) };
                })),
                spf ? spfLookups(spf) : Promise.resolve(0),
            ]);
            const dmarc = Array.isArray(dmarcTxt) ? (dmarcTxt.map(unq).find(t => /^v=dmarc1/i.test(t)) || null) : null;
            const sts = Array.isArray(stsTxt) ? (stsTxt.map(unq).find(t => /^v=stsv1/i.test(t)) || null) : null;
            const dkim = dkimChecks.find(Boolean);
            const prov = mailProvider(m.mxList);

            // MX
            const mxHtml = mxInfo.length ? mxInfo.map(x => {
                const ptrPill = !x.ip ? '' : (x.ptr ? (x.fcrdns ? pill('PTR confere', 'ok') : pill('PTR não confere', 'warn')) : pill('sem PTR', 'warn'));
                return `<div class="mx-row"><span class="mx-p">${x.pri}</span><span class="mx-h">${esc(x.host)}</span><span class="mx-ip">${esc(x.ip || '—')}${x.ptr ? `<small>${esc(x.ptr)}</small>` : ''}</span>${ptrPill}</div>`;
            }).join('') : `<div class="callout warn" style="margin:0;">Nenhum registro MX encontrado${m.ip ? ' — o e-mail usaria mail.' + esc(domain) + ' diretamente.' : '.'}</div>`;

            // SPF
            let spfPill, spfDet, spfStatus;
            if (!spf) { spfPill = pill('ausente', 'warn'); spfDet = 'Sem SPF: servidores de destino podem tratar o e-mail como suspeito.'; spfStatus = 'warn'; }
            else {
                const q = (spf.match(/(?:^|\s)([+\-~?]?)all\b/i) || [])[1];
                const pol = q === '-' ? ['rígida (-all)', 'ok'] : q === '~' ? ['branda (~all)', 'ok'] : q === '?' ? ['neutra (?all)', 'warn'] : (q === '+' || q === '') ? ['aberta (+all) — perigoso', 'fail'] : q === undefined && !/redirect=/i.test(spf) ? ['sem "all" no final', 'warn'] : ['via redirect', 'ok'];
                spfStatus = pol[1];
                let det = `Política ${pol[0]} · ~${spfN} consulta(s) DNS (limite 10)`;
                if (spfN > 10) { spfStatus = 'fail'; det += ' — <strong>excede o limite (PermError)</strong>'; }
                if (spfs.length > 1) { spfStatus = 'fail'; det += ` — <strong>${spfs.length} registros SPF</strong> (só pode haver 1)`; }
                spfPill = pill(spfStatus === 'ok' ? 'encontrado' : (spfStatus === 'warn' ? 'verificar' : 'problema'), spfStatus); spfDet = det;
            }
            // DMARC
            let dmPill, dmDet, dmStatus;
            if (!dmarc) { dmPill = pill('ausente', 'warn'); dmDet = 'Sem DMARC: nenhuma política de autenticação publicada.'; dmStatus = 'warn'; }
            else {
                const tag = k => (dmarc.match(new RegExp('(?:^|;)\\s*' + k + '=([^;]+)', 'i')) || [])[1];
                const p = (tag('p') || '?').trim().toLowerCase(), pct = tag('pct'), rua = tag('rua');
                dmStatus = (p === 'reject' || p === 'quarantine') ? 'ok' : 'warn';
                dmPill = pill(`p=${esc(p)}`, dmStatus);
                dmDet = `${p === 'none' ? 'Só monitora (não bloqueia).' : 'Política ativa.'}${pct ? ` pct=${esc(pct.trim())}%.` : ''}${rua ? ` Relatórios: ${esc(rua.trim())}.` : ' Sem endereço de relatórios (rua).'}`;
            }
            const dkPill = dkim ? pill('encontrado', 'ok') : pill('checar no painel', 'mut');
            const dkDet = dkim ? `Seletor <code>${esc(dkim.sel)}</code>.` : `Nenhum seletor comum encontrado (${DKIM_GUESSES.map(esc).join(', ')}) — o seletor pode ter outro nome.`;

            setCard(ctx, 'mail',
                `<div style="margin-bottom:8px;display:flex;gap:6px;flex-wrap:wrap;">${prov ? pill('Provedor: ' + esc(prov), 'ok') : ''}${m.mxList.length ? pill(m.mxList.length + ' MX', 'mut') : ''}</div>
         ${mxHtml}
         <div class="auth-grid">
           ${authTile('SPF', spfPill, spfDet, spf)}
           ${authTile('DKIM', dkPill, dkDet, dkim && dkim.val)}
           ${authTile('DMARC', dmPill, dmDet, dmarc)}
           ${authTile('MTA-STS', sts ? pill('encontrado', 'ok') : pill('opcional', 'mut'), sts ? 'Política de TLS para entrega publicada.' : 'Não configurado (recurso opcional de segurança).', sts)}
         </div>`,
                '');
            addCheck(ctx, 'mx', 'MX', m.mxList.length ? 'ok' : (m.ip ? 'warn' : 'fail'), 2);
            addCheck(ctx, 'spf', 'SPF', spfStatus, 2);
            addCheck(ctx, 'dkim', 'DKIM', dkim ? 'ok' : 'warn', 1);
            addCheck(ctx, 'dmarc', 'DMARC', dmStatus, 2);
            if (mxInfo.length) { const f = mxInfo[0]; const selfHosted = !prov || prov === 'Hostweb/Secrelnet'; addCheck(ctx, 'ptr', 'PTR', (f.ip && selfHosted) ? (f.ptr && f.fcrdns ? 'ok' : 'warn') : 'na', 1); }
            ctx.rep.mx = `MX: ${m.mxList.map(x => x.pri + ' ' + x.host).join(', ') || '—'}`;
            ctx.rep.spf = `SPF: ${spf || 'não encontrado'}`;
            ctx.rep.dmarc = `DMARC: ${dmarc || 'não encontrado'}`;
            ctx.rep.dkim = `DKIM: ${dkim ? 'seletor ' + dkim.sel : 'não encontrado nos seletores comuns'}`;
        }),

        // 4) Blacklist
        guard('rbl', async () => {
            const [site, mail] = await Promise.all([pSite, pMail]);
            const ip = mail.ip || ipv4(site.values)[0] || null;
            if (!ip) {
                setCard(ctx, 'rbl', `<div class="callout info" style="margin:0;">Sem IP para consultar.</div>`, '');
                addCheck(ctx, 'rbl', 'Blacklist', 'na', 3); return;
            }
            const res = await Promise.all(RBLS.map(async r => ({ ...r, ...(await checkRbl(ip, r.zone)) })));
            const listed = res.filter(r => r.listed === true), clean = res.filter(r => r.listed === false), unk = res.filter(r => r.listed === null);
            const chips = res.map(r => {
                const cls = r.listed === true ? 'fail' : (r.listed === false ? 'ok' : '');
                const txt = r.listed === true ? 'LISTADO' : (r.listed === false ? 'limpo' : 'sem resposta');
                return `<div class="rbl ${cls}" title="${esc(r.detail || '')}"><i></i><span>${esc(r.label)}</span><b>${txt}</b></div>`;
            }).join('');
            setCard(ctx, 'rbl',
                `<div class="rbl-sum">IP <code>${esc(ip)}</code> · <strong>${listed.length}</strong> de ${res.length} listas</div>
         <div class="rbl-grid">${chips}</div>
         ${listed.length ? `<div class="callout crit" style="margin-top:12px;">IP listado em pelo menos uma blacklist — isso explica e-mails caindo em spam ou sendo rejeitados. Consulte a categoria "Bloqueios &amp; blacklist" para os próximos passos.</div>` : ''}
         ${unk.length ? `<p class="lkc-foot">"Sem resposta" não significa limpo: listas como Spamhaus e Barracuda costumam recusar consultas de resolvers públicos. Para essas, confirme no <a href="https://mxtoolbox.com/SuperTool.aspx?action=blacklist%3a${esc(ip)}" target="_blank" rel="noopener">MXToolbox ↗</a>.</p>` : ''}`,
                listed.length ? pill('LISTADO', 'fail') : pill('limpo', 'ok'));
            addCheck(ctx, 'rbl', 'Blacklist', listed.length ? 'fail' : (clean.length ? 'ok' : 'na'), 3);
            ctx.rep.rbl = `Blacklist (${ip}): ${res.map(r => `${r.label}=${r.listed === true ? 'LISTADO' : (r.listed === false ? 'limpo' : 'sem resposta')}`).join(' | ')}`;
        }),

        // 5) Mapa DNS (estilo DNSdumpster)
        guard('dns', async () => {
            const [ns, txt, mx, extra, subs, site] = await Promise.all([pNs, pTxt, pMx, pExtra, pSubs, pSite]);
            const nsList = Array.isArray(ns) ? ns.map(n => n.replace(/\.$/, '').toLowerCase()) : [];
            const hostweb = nsList.some(n => /secrel\.com\.br/i.test(n));
            const txtList = Array.isArray(txt) ? txt.map(unq) : [];
            const [aaaa, soa, caa] = extra;
            const ttlA = site.ttl;
            const found = subs.filter(x => x.ans && x.ans.length);
            let n = 0;
            let h = `<div class="dm-g">Name servers ${hostweb ? pill('Hostweb/Secrelnet', 'ok') : pill('DNS externo', 'warn')}<span id="lkNsCmp"></span></div>`;
            h += nsList.length ? nsList.map(x => { n++; return recRow('NS', esc(x)); }).join('') : `<div class="dm-row"><span></span><span class="dm-v">—</span></div>`;
            h += `<p class="lkc-foot" style="margin:6px 0 0;">${hostweb ? 'Apontamentos A/MX podem ser alterados por aqui.' : 'Mudanças de MX/A precisam ser feitas no provedor de DNS do cliente.'}</p>`;
            h += `<div class="dm-g">Domínio (apex)</div>`;
            ipv4(site.values).forEach(ip => { n++; h += recRow('A', esc(ip), ttlA); });
            (aaaa || []).filter(a => a.type === 'AAAA').forEach(a => { n++; h += recRow('AAAA', esc(a.data), a.ttl); });
            if (Array.isArray(mx)) parseMx(mx).forEach(x => { n++; h += recRow('MX', `${x.pri} ${esc(x.host)}`); });
            (soa || []).filter(a => a.type === 'SOA').forEach(a => { n++; const p = a.data.split(' '); h += recRow('SOA', `${esc((p[0] || '').replace(/\.$/, ''))} <em>· serial ${esc(p[2] || '?')}</em>`, a.ttl); });
            (caa || []).filter(a => a.type === 'CAA').forEach(a => { n++; h += recRow('CAA', esc(a.data), a.ttl); });
            if (found.length) {
                h += `<div class="dm-g">Subdomínios comuns <span class="pill mut">${found.length} de ${SUBS.length} existem</span></div>`;
                found.forEach(x => {
                    n++;
                    const chain = x.ans.map(a => esc(a.data.replace(/\.$/, ''))).join(' → ');
                    h += recRow(x.ans[0].type === 'CNAME' ? 'CNAME' : 'A', `${esc(x.s)}<em>.${esc(domain)}</em> → ${chain}`, x.ans[0].ttl);
                });
            }
            if (txtList.length) {
                h += `<div class="dm-g">TXT <span class="pill mut">${txtList.length}</span></div>`;
                txtList.forEach(t => { n++; h += `<div class="dm-row"><span class="rt">TXT</span><span class="dm-v" title="${esc(t)}">${esc(t.length > 170 ? t.slice(0, 170) + '…' : t)}</span><span></span></div>`; });
            }
            h += `<button class="lk-btn" id="lkCt">🔭 Descobrir mais subdomínios (certificados públicos)</button><div id="lkCtOut"></div>`;
            setCard(ctx, 'dns', h, pill(n + ' registros', 'mut'));
            const ctBtn = document.getElementById('lkCt');
            if (ctBtn) ctBtn.addEventListener('click', () => discoverSubdomains(ctx));
            ctx.rep.ns = `NS: ${nsList.join(', ') || '—'}  (${hostweb ? 'Hostweb' : 'externo'})`;

            // compara com o RDAP assim que ele chegar (sem travar o resto do card)
            pRdap.then(r => {
                if (ctx.token !== lookupToken) return;
                const slot = document.getElementById('lkNsCmp');
                if (!slot || !r.ok || !r.nameservers.length || !nsList.length) return;
                const live = new Set(nsList), reg = new Set(r.nameservers);
                const same = live.size === reg.size && [...live].every(x => reg.has(x));
                slot.innerHTML = same ? pill('confere com o registro (RDAP)', 'ok') : `${pill('diverge do RDAP', 'warn')}`;
                if (!same) slot.title = 'Registro lista: ' + r.nameservers.join(', ');
                addCheck(ctx, 'ns', 'NS × registro', same ? 'ok' : 'warn', 2);
                if (!same) ctx.rep.ns += `  |  ATENÇÃO: registro lista ${r.nameservers.join(', ')}`;
            });
        }),

        // 6) Assinatura do servidor de e-mail (alternativa ao banner de telnet)
        guard('fp', async () => {
            const m = await pMail;
            const ptr = m.ip ? await getPtr(m.ip) : null;
            const ev = []; let verdict, conf, tone;
            const emailSrv = m.ip ? matchEmailServer(m.ip) : null;
            const plesk = m.ip ? matchByList(m.ip, PLESK_SERVERS) : null;
            const prov = mailProvider(m.mxList);
            if (m.mxList.length) ev.push(`MX principal: <code>${esc(m.mxList[0].host)}</code> (prioridade ${m.mxList[0].pri})`);
            if (m.ip) ev.push(`IP de e-mail: <code>${esc(m.ip)}</code>`);
            ev.push(ptr ? `PTR (DNS reverso): <code>${esc(ptr)}</code>` : 'Sem PTR (DNS reverso) para o IP de e-mail');
            if (!m.mxList.length && !m.ip) { verdict = 'Sem e-mail configurado'; conf = ['—', 'mut']; tone = 'mut'; }
            else if (emailSrv) { verdict = `cPanel (Exim + Dovecot) — ${emailSrv.name}`; conf = ['alta', 'ok']; ev.unshift(`IP dentro da faixa do servidor de e-mail <strong>${esc(emailSrv.name)}</strong>`); }
            else if (plesk) { verdict = `Plesk — ${plesk.name}`; conf = ['média', 'warn']; ev.unshift(`IP coincide com o <strong>${esc(plesk.name)}</strong> (Plesk costuma usar Postfix + Dovecot)`); }
            else if (prov && prov !== 'Hostweb/Secrelnet') { verdict = `Provedor externo — ${prov}`; conf = ['alta', 'ok']; ev.unshift(`O MX aponta para <strong>${esc(prov)}</strong>`); }
            else if (prov === 'Hostweb/Secrelnet' || (ptr && /secrel\.com\.br|hostweb\.com\.br/i.test(ptr))) { verdict = 'Infraestrutura Hostweb — Postfix/Zimbra'; conf = ['média', 'warn']; ev.unshift('Hostname do MX/PTR pertence à Hostweb/Secrelnet, mas o IP não está nas faixas cPanel conhecidas'); }
            else { verdict = 'Provável Postfix/Zimbra'; conf = ['baixa', 'mut']; ev.unshift('IP fora das faixas cPanel conhecidas e sem provedor externo reconhecido no MX'); }
            const host = 'mail.' + domain;
            const cmds = [
                ['Entrada (POP3) — o banner mostra o software', `telnet ${host} 110`],
                ['Saída (submission)', `telnet ${host} 587`],
                ['SMTP (porta 25)', `telnet ${host} 25`],
                ['Conferir MX pelo prompt', `nslookup -type=mx ${domain}`],
            ];
            setCard(ctx, 'fp',
                `<div class="fp-verdict">${esc(verdict)}</div>
         <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;"><span style="font-size:11.5px;color:var(--ink-faint);">confiança</span>${pill(conf[0], conf[1])}<span style="font-size:11.5px;color:var(--ink-faint);">· inferência por sinais indiretos, não é o banner real</span></div>
         <ul class="fp-ev">${ev.map(e => `<li>${e}</li>`).join('')}</ul>
         <div class="dm-g" style="margin-top:4px;">Para confirmar o banner (telnet) — comandos prontos</div>
         ${cmds.map(c => `<div class="cmd"><div><small>${esc(c[0])}</small><code>${esc(c[1])}</code></div><button data-copy="${esc(c[1])}">copiar</button></div>`).join('')}`,
                pill('confiança ' + conf[0], conf[1]));
            ctx.rep.fp = `Assinatura do servidor de e-mail: ${verdict} (confiança ${conf[0]})${(prov && prov !== 'Hostweb/Secrelnet') ? '' : ' — confirmar com: telnet ' + host + ' 110'}`;
        }),
    ]);
}

// Subdomínios a partir de certificados públicos (Certificate Transparency via crt.sh) — sob demanda
async function discoverSubdomains(ctx) {
    const out = document.getElementById('lkCtOut'), btn = document.getElementById('lkCt');
    if (!out) return;
    btn.disabled = true;
    out.innerHTML = `<p class="lkc-foot"><span class="spinner"></span> &nbsp;Consultando logs de transparência de certificados (pode levar até ~15s)…</p>`;
    try {
        const res = await fetchT(`https://crt.sh/?q=%25.${encodeURIComponent(ctx.domain)}&output=json`, {}, 15000);
        if (!res.ok) throw new Error('HTTP ' + res.status);
        const rows = await res.json();
        const set = new Set();
        rows.forEach(r => String(r.name_value || '').split('\n').forEach(n => {
            n = n.trim().toLowerCase().replace(/^\*\./, '');
            if (n && (n === ctx.domain || n.endsWith('.' + ctx.domain))) set.add(n);
        }));
        const list = [...set].sort();
        out.innerHTML = list.length
            ? `<p class="lkc-foot" style="margin-top:12px;">${list.length} nome(s) em certificados emitidos${list.length > 80 ? ' (mostrando 80)' : ''}. Podem incluir nomes que já não existem.</p><div class="ct-chips">${list.slice(0, 80).map(n => `<span>${esc(n)}</span>`).join('')}</div>`
            : `<p class="lkc-foot">Nenhum certificado público encontrado para este domínio.</p>`;
    } catch (e) {
        out.innerHTML = `<div class="callout warn" style="margin-top:12px;">O crt.sh não respondeu ou bloqueou o acesso direto do navegador. Tente pelo site: <a href="https://crt.sh/?q=${encodeURIComponent(ctx.domain)}" target="_blank" rel="noopener">crt.sh ↗</a></div>`;
    } finally { btn.disabled = false; }
}

function copyLookupResult() {
    if (!lastLookupText) return;
    navigator.clipboard.writeText(lastLookupText).then(() => {
        const btn = document.getElementById('lkCopy');
        const old = btn.textContent;
        btn.textContent = 'Copiado ✓';
        setTimeout(() => { btn.textContent = old; }, 1500);
    });
}

