/* ============================================================
   FRASES PRONTAS — render (com edição pela equipe)
   ============================================================ */
let phrasesGroupFilter = 'all';

// Persistência local (por navegador/computador — ver nota na tela)
const LS_OVERRIDES = 'hw_phrases_overrides_v1'; // edições de frases originais: {"grupo::idx": "texto"}
const LS_SIT = 'hw_phrases_sit_v1';              // edições de título: {"grupo::idx": "título"}
const LS_CUSTOM = 'hw_phrases_custom_v1';        // frases novas por grupo: {"grupo":[{sit,text}]}

function lsGet(key) { try { return JSON.parse(localStorage.getItem(key) || '{}'); } catch (e) { return {}; } }
function lsSet(key, obj) { try { localStorage.setItem(key, JSON.stringify(obj)); } catch (e) { } }
function escAttr(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/"/g, '&quot;'); }

function getEffectiveItem(group, idx, def) {
    const ov = lsGet(LS_OVERRIDES);
    const sv = lsGet(LS_SIT);
    const k = `${group}::${idx}`;
    return {
        sit: sv[k] !== undefined ? sv[k] : def.sit,
        text: ov[k] !== undefined ? ov[k] : def.text,
        edited: ov[k] !== undefined || sv[k] !== undefined,
    };
}

function renderPhrases() {
    cardArea.style.display = 'none';
    flowArea.style.display = 'none';
    emptyState.style.display = 'none';
    document.getElementById('lookupArea').style.display = 'none';
    document.getElementById('practicesArea').style.display = 'none';
    document.getElementById('notesArea').style.display = 'none';
    document.getElementById('researchArea').style.display = 'none';
    const ph = document.getElementById('phrasesArea');
    ph.style.display = 'block';
    pagehead.querySelector('h1').textContent = 'Frases prontas';
    pagehead.querySelector('p').textContent = 'Respostas técnicas para o cliente, em linguagem clara — copie, ajuste os campos entre colchetes e envie.';
    resultCount.textContent = '';

    const chips = [{ group: 'all', label: 'Tudo' }].concat(PHRASES.map(g => ({ group: g.group, label: g.group })));
    let html = `<div class="ph-toolbar">
    ${chips.map(c => `<button class="ph-filter-chip ${phrasesGroupFilter === c.group ? 'active' : ''}" data-group="${escAttr(c.group)}">${c.label}</button>`).join('')}
    <span class="spacer"></span>
    <button class="ph-iobtn" id="phExport">Exportar edições</button>
    <button class="ph-iobtn" id="phImport">Importar edições</button>
    <input type="file" id="phImportFile" accept="application/json" style="display:none;">
  </div>
  <p class="ph-note">Os textos abaixo são editáveis — clique e altere direto na caixa. As mudanças salvam automaticamente <strong>neste navegador</strong> (não sincronizam sozinhas entre computadores da equipe). Use "Exportar edições" para gerar um arquivo e compartilhar/importar em outra máquina.</p>`;

    const groupsToShow = phrasesGroupFilter === 'all' ? PHRASES : PHRASES.filter(g => g.group === phrasesGroupFilter);
    const customAll = lsGet(LS_CUSTOM);

    html += groupsToShow.map((g) => {
        const customItems = customAll[g.group] || [];
        return `
    <div class="ph-group">
      <div class="ph-group-head">
        <div class="ico" style="background:var(--subtle-bg); color:var(--ink-soft);">${g.icon}</div>
        <h3>${g.group}</h3>
      </div>
      <div class="ph-grid">
        ${g.items.map((it, ii) => {
            const eff = getEffectiveItem(g.group, ii, it);
            return `
          <div class="ph-card ${eff.edited ? 'edited' : ''}" data-kind="builtin" data-group="${escAttr(g.group)}" data-idx="${ii}">
            <div class="ph-sit-row">
              <input class="ph-sit-input" value="${escAttr(eff.sit)}">
              ${eff.edited ? '<span class="ph-edited-badge">editado</span>' : ''}
            </div>
            <textarea class="ph-text-edit">${eff.text}</textarea>
            <div class="ph-card-actions">
              <button class="ph-copy">Copiar frase</button>
              ${eff.edited ? '<button class="ph-restore">restaurar original</button>' : ''}
            </div>
          </div>`;
        }).join('')}
        ${customItems.map((it, ci) => `
          <div class="ph-card edited" data-kind="custom" data-group="${escAttr(g.group)}" data-idx="${ci}">
            <div class="ph-sit-row">
              <input class="ph-sit-input" value="${escAttr(it.sit)}" placeholder="Situação (título da frase)">
              <span class="ph-edited-badge">nova</span>
            </div>
            <textarea class="ph-text-edit" placeholder="Escreva a frase aqui...">${it.text || ''}</textarea>
            <div class="ph-card-actions">
              <button class="ph-copy">Copiar frase</button>
              <button class="ph-delete">excluir</button>
            </div>
          </div>
        `).join('')}
        <div class="ph-add-card" data-group="${escAttr(g.group)}">+ Adicionar frase neste grupo</div>
      </div>
    </div>`;
    }).join('');

    ph.innerHTML = html;

    // filtros de grupo
    ph.querySelectorAll('.ph-filter-chip').forEach(chip => {
        chip.addEventListener('click', () => {
            phrasesGroupFilter = chip.dataset.group;
            renderPhrases();
        });
    });

    // copiar (lê o valor ATUAL da textarea, já com edições)
    ph.querySelectorAll('.ph-copy').forEach(btn => {
        btn.addEventListener('click', () => {
            const card = btn.closest('.ph-card');
            const text = card.querySelector('.ph-text-edit').value;
            navigator.clipboard.writeText(text).then(() => {
                const old = btn.textContent;
                btn.textContent = 'Copiado ✓';
                btn.classList.add('done');
                setTimeout(() => { btn.textContent = old; btn.classList.remove('done'); }, 1500);
            });
        });
    });

    // edição de frases originais (salva em overrides)
    ph.querySelectorAll('.ph-card[data-kind="builtin"]').forEach(card => {
        const group = card.dataset.group, idx = card.dataset.idx;
        const key = `${group}::${idx}`;
        const sitInput = card.querySelector('.ph-sit-input');
        const textArea = card.querySelector('.ph-text-edit');
        sitInput.addEventListener('blur', () => {
            const def = PHRASES.find(g => g.group === group).items[parseInt(idx, 10)];
            const sv = lsGet(LS_SIT);
            if (sitInput.value !== def.sit) { sv[key] = sitInput.value; } else { delete sv[key]; }
            lsSet(LS_SIT, sv);
            renderPhrases();
        });
        textArea.addEventListener('blur', () => {
            const def = PHRASES.find(g => g.group === group).items[parseInt(idx, 10)];
            const ov = lsGet(LS_OVERRIDES);
            if (textArea.value !== def.text) { ov[key] = textArea.value; } else { delete ov[key]; }
            lsSet(LS_OVERRIDES, ov);
            renderPhrases();
        });
    });
    ph.querySelectorAll('.ph-restore').forEach(btn => {
        btn.addEventListener('click', () => {
            const card = btn.closest('.ph-card');
            const group = card.dataset.group, idx = card.dataset.idx;
            const key = `${group}::${idx}`;
            const ov = lsGet(LS_OVERRIDES); delete ov[key]; lsSet(LS_OVERRIDES, ov);
            const sv = lsGet(LS_SIT); delete sv[key]; lsSet(LS_SIT, sv);
            renderPhrases();
        });
    });

    // frases novas (custom)
    ph.querySelectorAll('.ph-card[data-kind="custom"]').forEach(card => {
        const group = card.dataset.group, idx = parseInt(card.dataset.idx, 10);
        const sitInput = card.querySelector('.ph-sit-input');
        const textArea = card.querySelector('.ph-text-edit');
        const saveCustom = () => {
            const all = lsGet(LS_CUSTOM);
            if (!all[group]) all[group] = [];
            all[group][idx] = { sit: sitInput.value || 'Nova situação', text: textArea.value };
            lsSet(LS_CUSTOM, all);
        };
        sitInput.addEventListener('blur', () => { saveCustom(); renderPhrases(); });
        textArea.addEventListener('blur', () => { saveCustom(); renderPhrases(); });
        card.querySelector('.ph-delete').addEventListener('click', () => {
            const all = lsGet(LS_CUSTOM);
            (all[group] || []).splice(idx, 1);
            lsSet(LS_CUSTOM, all);
            renderPhrases();
        });
    });

    // adicionar nova frase
    ph.querySelectorAll('.ph-add-card').forEach(addBtn => {
        addBtn.addEventListener('click', () => {
            const group = addBtn.dataset.group;
            const all = lsGet(LS_CUSTOM);
            if (!all[group]) all[group] = [];
            all[group].push({ sit: 'Nova situação', text: '' });
            lsSet(LS_CUSTOM, all);
            renderPhrases();
        });
    });

    // exportar edições
    document.getElementById('phExport').addEventListener('click', () => {
        const payload = { overrides: lsGet(LS_OVERRIDES), sit: lsGet(LS_SIT), custom: lsGet(LS_CUSTOM) };
        const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = 'frases-prontas-edicoes.json';
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        URL.revokeObjectURL(url);
    });

    // importar edições
    const importFile = document.getElementById('phImportFile');
    document.getElementById('phImport').addEventListener('click', () => importFile.click());
    importFile.addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = () => {
            try {
                const data = JSON.parse(reader.result);
                if (data.overrides) lsSet(LS_OVERRIDES, { ...lsGet(LS_OVERRIDES), ...data.overrides });
                if (data.sit) lsSet(LS_SIT, { ...lsGet(LS_SIT), ...data.sit });
                if (data.custom) {
                    const cur = lsGet(LS_CUSTOM);
                    for (const grp in data.custom) { cur[grp] = data.custom[grp]; }
                    lsSet(LS_CUSTOM, cur);
                }
                renderPhrases();
            } catch (err) {
                alert('Arquivo inválido. Exporte um arquivo gerado pelo botão "Exportar edições" desta mesma ferramenta.');
            }
        };
        reader.readAsText(file);
        importFile.value = '';
    });
}

/* ============================================================
   ANOTAÇÕES — checklists (múltiplos, independentes) + notas livres por dia
   ============================================================ */
const LS_NOTES = 'hw_notes_v1';            // {"2026-08-26": {text:"..."}}  (checklist antigo migrado)
const LS_CHECKLISTS = 'hw_checklists_v1';  // [{id, title, items:[{text,done}]}]
const LS_CHECKLISTS_MIGRATED = 'hw_checklists_migrated_v1';

let notesCurrentDate = todayStr();

function todayStr() {
    const d = new Date();
    const pad = n => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}
function shiftDateStr(dateStr, delta) {
    const [y, m, d] = dateStr.split('-').map(Number);
    const dt = new Date(y, m - 1, d);
    dt.setDate(dt.getDate() + delta);
    const pad = n => String(n).padStart(2, '0');
    return `${dt.getFullYear()}-${pad(dt.getMonth() + 1)}-${pad(dt.getDate())}`;
}
function formatDateBR(dateStr) {
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${y}`;
}
function getAllNotes() { try { return JSON.parse(localStorage.getItem(LS_NOTES) || '{}'); } catch (e) { return {}; } }
function setAllNotes(obj) { try { localStorage.setItem(LS_NOTES, JSON.stringify(obj)); } catch (e) { } }
function getDayNotes(dateStr) {
    const all = getAllNotes();
    return all[dateStr] || { text: '' };
}
function setDayNotes(dateStr, data) {
    const all = getAllNotes();
    all[dateStr] = data;
    setAllNotes(all);
}

function genChecklistId() { return 'cl_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }
function getChecklists() { try { return JSON.parse(localStorage.getItem(LS_CHECKLISTS) || '[]'); } catch (e) { return []; } }
function setChecklists(arr) { try { localStorage.setItem(LS_CHECKLISTS, JSON.stringify(arr)); } catch (e) { } }

// Migra, uma única vez, checklists antigos (que ficavam presos ao dia) para a nova lista de checklists nomeados.
function migrateOldChecklists() {
    if (localStorage.getItem(LS_CHECKLISTS_MIGRATED)) return;
    try {
        const oldNotes = getAllNotes();
        const migrated = [];
        Object.keys(oldNotes).sort().forEach(dateStr => {
            const day = oldNotes[dateStr];
            if (day && Array.isArray(day.checklist) && day.checklist.length) {
                migrated.push({ id: genChecklistId(), title: `Checklist — ${formatDateBR(dateStr)}`, items: day.checklist });
                delete day.checklist;
            }
        });
        if (migrated.length) {
            setChecklists(getChecklists().concat(migrated));
            setAllNotes(oldNotes);
        }
    } catch (e) { }
    localStorage.setItem(LS_CHECKLISTS_MIGRATED, '1');
}

function renderNotes() {
    cardArea.style.display = 'none';
    flowArea.style.display = 'none';
    emptyState.style.display = 'none';
    document.getElementById('lookupArea').style.display = 'none';
    document.getElementById('practicesArea').style.display = 'none';
    document.getElementById('phrasesArea').style.display = 'none';
    document.getElementById('researchArea').style.display = 'none';
    const nt = document.getElementById('notesArea');
    nt.style.display = 'block';
    pagehead.querySelector('h1').textContent = 'Anotações';
    pagehead.querySelector('p').textContent = 'Crie quantos checklists precisar e registre anotações livres do dia a dia — tudo salvo automaticamente neste navegador.';
    resultCount.textContent = '';

    migrateOldChecklists();

    const day = getDayNotes(notesCurrentDate);
    const isToday = notesCurrentDate === todayStr();

    nt.innerHTML = `
    <div class="nt-toolbar">
      <button class="nt-datebtn" id="ntPrev">← dia anterior</button>
      <input type="date" class="nt-dateinput" id="ntDatePick" value="${notesCurrentDate}">
      <button class="nt-datebtn" id="ntNext">dia seguinte →</button>
      ${isToday ? '<span class="nt-today-pill">Hoje</span>' : `<button class="nt-datebtn" id="ntToday">ir para hoje</button>`}
      <span class="spacer"></span>
      <button class="nt-exportbtn" id="ntExport">Exportar (.txt)</button>
    </div>
    <div class="nt-grid">
      <div class="nt-panel">
        <div class="nt-panel-head">
          <h3><span class="ico">✓</span>Checklists</h3>
          <button class="nt-newclist-btn" id="ntNewChecklistBtn">+ Novo checklist</button>
        </div>
        <div class="nt-checklists-wrap" id="ntChecklistsWrap"></div>
      </div>
      <div class="nt-panel">
        <h3><span class="ico">✎</span>Anotações livres do dia</h3>
        <textarea class="nt-freetext" id="ntFreeText" placeholder="Escreva aqui observações, lembretes, o que quiser registrar sobre o dia...">${day.text || ''}</textarea>
        <div class="nt-savedhint" id="ntSavedHint">salvo automaticamente</div>
      </div>
    </div>
  `;

    renderChecklistsPanel();

    document.getElementById('ntNewChecklistBtn').addEventListener('click', createChecklist);

    let saveTimer = null;
    document.getElementById('ntFreeText').addEventListener('input', (e) => {
        const hint = document.getElementById('ntSavedHint');
        hint.textContent = 'salvando...';
        clearTimeout(saveTimer);
        saveTimer = setTimeout(() => {
            const d = getDayNotes(notesCurrentDate);
            d.text = e.target.value;
            setDayNotes(notesCurrentDate, d);
            hint.textContent = 'salvo automaticamente';
        }, 400);
    });

    document.getElementById('ntDatePick').addEventListener('change', (e) => {
        if (e.target.value) { notesCurrentDate = e.target.value; renderNotes(); }
    });
    document.getElementById('ntPrev').addEventListener('click', () => {
        notesCurrentDate = shiftDateStr(notesCurrentDate, -1); renderNotes();
    });
    document.getElementById('ntNext').addEventListener('click', () => {
        notesCurrentDate = shiftDateStr(notesCurrentDate, 1); renderNotes();
    });
    const todayBtn = document.getElementById('ntToday');
    if (todayBtn) {
        todayBtn.addEventListener('click', () => {
            notesCurrentDate = todayStr(); renderNotes();
        });
    }

    document.getElementById('ntExport').addEventListener('click', () => {
        const d = getDayNotes(notesCurrentDate);
        const lists = getChecklists();
        let out = `Anotações — ${formatDateBR(notesCurrentDate)}\n`;
        out += '='.repeat(30) + '\n\n';
        out += 'Anotações do dia:\n';
        out += (d.text && d.text.trim()) ? d.text : '(sem anotações)';
        out += '\n\n' + '-'.repeat(30) + '\n';
        out += 'Checklists:\n\n';
        if (lists.length) {
            lists.forEach(cl => {
                out += `• ${cl.title}\n`;
                if (cl.items && cl.items.length) {
                    cl.items.forEach(it => { out += `  [${it.done ? 'x' : ' '}] ${it.text}\n`; });
                } else {
                    out += '  (nenhum item)\n';
                }
                out += '\n';
            });
        } else {
            out += '(nenhum checklist criado)\n';
        }

        const blob = new Blob([out], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `anotacoes_${notesCurrentDate}.txt`;
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        URL.revokeObjectURL(url);
    });
}

function renderChecklistsPanel() {
    const wrap = document.getElementById('ntChecklistsWrap');
    const lists = getChecklists();

    if (!lists.length) {
        wrap.innerHTML = `<div class="nt-checklists-empty">Nenhum checklist criado ainda.<br>
      <button class="nt-newclist-btn" id="ntEmptyNewBtn">+ Criar checklist</button></div>`;
        document.getElementById('ntEmptyNewBtn').addEventListener('click', createChecklist);
        return;
    }

    wrap.innerHTML = lists.map(cl => `
    <div class="nt-cl-card" data-id="${cl.id}">
      <div class="nt-cl-head">
        <input type="text" class="nt-cl-title-input" value="${escAttr(cl.title)}" placeholder="Nome do checklist">
        <button class="nt-cl-del" title="Excluir checklist">✕</button>
      </div>
      <div class="nt-addrow">
        <input type="text" class="nt-cl-newitem" placeholder="Adicionar item e pressionar Enter...">
        <button class="nt-cl-additembtn">Adicionar</button>
      </div>
      <div class="nt-checklist"></div>
    </div>
  `).join('');

    wrap.querySelectorAll('.nt-cl-card').forEach(card => {
        const id = card.dataset.id;
        const cl = getChecklists().find(c => c.id === id);
        if (!cl) return;
        renderChecklistItems(card.querySelector('.nt-checklist'), id, cl.items || []);

        card.querySelector('.nt-cl-title-input').addEventListener('blur', (e) => {
            const all = getChecklists();
            const item = all.find(c => c.id === id);
            if (item) { item.title = e.target.value.trim() || 'Checklist sem nome'; setChecklists(all); }
            if (e.target.value.trim() === '') e.target.value = 'Checklist sem nome';
        });

        card.querySelector('.nt-cl-del').addEventListener('click', () => {
            if (!confirm(`Excluir o checklist "${cl.title}" e todos os itens dele? Essa ação não pode ser desfeita.`)) return;
            setChecklists(getChecklists().filter(c => c.id !== id));
            renderChecklistsPanel();
        });

        const addItemFn = () => {
            const input = card.querySelector('.nt-cl-newitem');
            const val = input.value.trim();
            if (!val) return;
            const all = getChecklists();
            const item = all.find(c => c.id === id);
            item.items = item.items || [];
            item.items.push({ text: val, done: false });
            setChecklists(all);
            input.value = '';
            renderChecklistItems(card.querySelector('.nt-checklist'), id, item.items);
            input.focus();
        };
        card.querySelector('.nt-cl-additembtn').addEventListener('click', addItemFn);
        card.querySelector('.nt-cl-newitem').addEventListener('keydown', (e) => {
            if (e.key === 'Enter') { e.preventDefault(); addItemFn(); }
        });
    });
}

function renderChecklistItems(box, listId, items) {
    if (!items.length) {
        box.innerHTML = '<div class="nt-empty-small">Nenhum item ainda.</div>';
        return;
    }
    box.innerHTML = items.map((it, i) => `
    <div class="nt-item ${it.done ? 'done' : ''}" data-idx="${i}">
      <input type="checkbox" ${it.done ? 'checked' : ''}>
      <div class="txt">${escAttr(it.text)}</div>
      <button class="del" title="Excluir">✕</button>
    </div>
  `).join('');
    box.querySelectorAll('.nt-item').forEach(row => {
        const idx = parseInt(row.dataset.idx, 10);
        row.querySelector('input[type="checkbox"]').addEventListener('change', (e) => {
            const all = getChecklists();
            const cl = all.find(c => c.id === listId);
            cl.items[idx].done = e.target.checked;
            setChecklists(all);
            row.classList.toggle('done', e.target.checked);
        });
        row.querySelector('.del').addEventListener('click', () => {
            const all = getChecklists();
            const cl = all.find(c => c.id === listId);
            cl.items.splice(idx, 1);
            setChecklists(all);
            renderChecklistItems(box, listId, cl.items);
        });
    });
}

function createChecklist() {
    const all = getChecklists();
    all.push({ id: genChecklistId(), title: `Checklist ${all.length + 1}`, items: [] });
    setChecklists(all);
    renderChecklistsPanel();
    setTimeout(() => {
        const cards = document.querySelectorAll('.nt-cl-card');
        const last = cards[cards.length - 1];
        if (last) {
            const inp = last.querySelector('.nt-cl-title-input');
            inp.focus(); inp.select();
        }
    }, 0);
}

// Nav
document.querySelectorAll('.navbtn').forEach(btn => {
    btn.addEventListener('click', () => {
        document.querySelectorAll('.navbtn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const cat = btn.dataset.cat;
        if (cat === 'flow') {
            renderFlowPicker();
        } else if (cat === 'lookup') {
            renderLookupShell();
        } else if (cat === 'practices') {
            renderPractices();
        } else if (cat === 'phrases') {
            renderPhrases();
        } else if (cat === 'notes') {
            renderNotes();
        } else if (cat === 'research') {
            renderResearch();
        } else {
            currentCat = cat;
            renderCards();
        }
    });
});

searchInput.addEventListener('input', (e) => {
    currentQuery = e.target.value;
    // if searching, force out of flow mode into "all" results
    if (currentQuery.trim().length > 0) {
        document.querySelectorAll('.navbtn').forEach(b => b.classList.remove('active'));
        document.querySelector('.navbtn[data-cat="all"]').classList.add('active');
        currentCat = 'all';
    }
    renderCards();
});

// init
renderCards();